content.content:
1	<title>Priorish x Akashic: what we have, what we need</title>
2	
3	<style>
4	/* report-kit -- the design system behind Akashic Aurora's visual reports.
5	 *
6	 * Daniil 2026-08-10, after three of them in two days: "Is there a way to verbify it so that
7	 * it is easier for you to make these?"
8	 *
9	 * THIS IS A SYSTEM, NOT A TEMPLATE, and the distinction is the whole design constraint. The
10	 * three reports that produced this kit needed three different SHAPES -- a retrospective, a
11	 * set of decision forks, a reconciliation built around a contradiction -- and the thing
12	 * Daniil was responding to was the fit. A generator that emitted a fixed document would
13	 * flatten exactly that. So: tokens and primitives here, composition every time.
14	 *
15	 * INLINED, NEVER LINKED. Published artifacts run under a CSP that blocks every external
16	 * host, so a <link> to this file would silently fall back to unstyled. The scaffold
17	 * generator inlines it at emit time; that is a requirement, not a convenience.
18	 *
19	 * SEMANTIC COLOUR IS SEPARATE FROM ACCENT. --go/--hold/--stop carry MEANING (this is cheap /
20	 * this needs judgement / this costs either way) and must never be spent on decoration.
21	 * --aurora is the accent and carries none. Mixing the two is how a design system becomes
22	 * wallpaper.
23	 */
24	
25	:root {
26	  /* Ground and structure. The neutrals are blue-biased toward the accent rather than pure
27	     grey -- a pure mid-grey reads as unconsidered. */
28	  --ground:#0A0F14; --surface:#111A22; --surface2:#17222C; --line:#22303E;
29	  --ink:#E3EAEF; --muted:#8798A6; --dim:#5F7080;
30	
31	  /* Semantic. Meaning only. */
32	  --go:#3FD3A0;      /* cheap, unblocked, shipped, confirmed */
33	  --hold:#E0A854;    /* needs judgement, pending, self-declared */
34	  --stop:#E4606A;    /* costs either way, refuted, not built */
35	  --aurora:#8B7FE8;  /* the accent. Structure and emphasis, never status. */
36	
37	  --mono:ui-monospace,"SF Mono","Cascadia Mono","Roboto Mono",Consolas,monospace;
38	  --sans:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
39	  --serif:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
40	}
41	
42	/* Both themes at TOKEN level: components style through the tokens and never inside the
43	   media query, so the data-theme override can win in BOTH directions. */
44	@media (prefers-color-scheme: light) {
45	  :root {
46	    --ground:#F7F8F9; --surface:#FFFFFF; --surface2:#F0F3F5; --line:#DCE3E8;
47	    --ink:#16202A; --muted:#5A6B79; --dim:#8496A3;
48	    --go:#137A5A; --hold:#9A6A17; --stop:#C43A45; --aurora:#5B4DC4;
49	  }
50	}
51	:root[data-theme="dark"] {
52	  --ground:#0A0F14; --surface:#111A22; --surface2:#17222C; --line:#22303E;
53	  --ink:#E3EAEF; --muted:#8798A6; --dim:#5F7080;
54	  --go:#3FD3A0; --hold:#E0A854; --stop:#E4606A; --aurora:#8B7FE8;
55	}
56	:root[data-theme="light"] {
57	  --ground:#F7F8F9; --surface:#FFFFFF; --surface2:#F0F3F5; --line:#DCE3E8;
58	  --ink:#16202A; --muted:#5A6B79; --dim:#8496A3;
59	  --go:#137A5A; --hold:#9A6A17; --stop:#C43A45; --aurora:#5B4DC4;
60	}
61	
62	body { background:var(--ground); color:var(--ink); font-family:var(--sans);
63	       line-height:1.62; margin:0; padding:0 20px 90px; }
64	.wrap { max-width:880px; margin:0 auto; }
65	h1,h2,h3 { text-wrap:balance; margin:0; }
66	p { margin:0; }
67	a { color:var(--aurora); }
68	code { font-family:var(--mono); font-size:.88em; background:var(--surface2);
69	       padding:1.5px 5px; border-radius:3px; }
70	.num { font-variant-numeric:tabular-nums; }   /* any column of digits */
71	
72	/* --- header ------------------------------------------------------------------ */
73	header { padding:54px 0 24px; display:flex; flex-direction:column; gap:13px; }
74	.eyebrow { font-family:var(--mono); font-size:12px; letter-spacing:.14em;
75	           text-transform:uppercase; color:var(--muted); }
76	h1 { font-size:clamp(28px,4.6vw,40px); line-height:1.14; font-weight:640;
77	     letter-spacing:-.02em; }
78	.standfirst { font-family:var(--serif); font-size:18.5px; line-height:1.55;
79	              color:var(--muted); max-width:62ch; }
80	
81	/* --- rule: a section break that carries the project's name ------------------- */
82	hr.rule { height:2px; border:0; margin:0; opacity:.5;
83	  background:linear-gradient(90deg,transparent,var(--go) 18%,var(--aurora) 52%,
84	             var(--stop) 80%,transparent); }
85	
86	section { margin-top:46px; display:flex; flex-direction:column; gap:16px; }
87	h2 { font-size:12.5px; font-family:var(--mono); letter-spacing:.16em;
88	     text-transform:uppercase; color:var(--muted); font-weight:600; }
89	h3 { font-size:20px; font-weight:620; letter-spacing:-.01em; }
90	.prose { max-width:68ch; color:var(--muted); font-size:15.5px; }
91	.prose strong { color:var(--ink); }
92	
93	/* --- tiles: headline numbers. Use for 3-6 figures, never for prose. ---------- */
94	.tiles { display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:10px; }
95	.tile { background:var(--surface); border:1px solid var(--line); border-radius:4px;
96	        padding:14px 16px; display:flex; flex-direction:column; gap:3px; }
97	.tile .v { font-family:var(--mono); font-size:26px; font-weight:600; letter-spacing:-.02em;
98	           font-variant-numeric:tabular-nums; }
99	.tile .k { font-family:var(--mono); font-size:11px; letter-spacing:.1em;
100	           text-transform:uppercase; color:var(--dim); }
101	
102	/* --- card + paths: A DECISION WITH REAL COSTS ON BOTH SIDES ------------------
103	   Use ONLY when both directions genuinely cost something. A card whose second path is
104	   obviously wrong is a rhetorical device pretending to be a choice. */
105	.card { background:var(--surface); border:1px solid var(--line); border-radius:5px;
106	        border-left:3px solid var(--line); overflow:hidden; }
107	.card.go { border-left-color:var(--go); }
108	.card.hold { border-left-color:var(--hold); }
109	.card.stop { border-left-color:var(--stop); }
110	.card .head { padding:17px 20px 13px; display:flex; flex-direction:column; gap:7px; }
111	.card .tid { font-family:var(--mono); font-size:11px; letter-spacing:.08em; color:var(--dim); }
112	.card .title { font-size:19px; font-weight:620; letter-spacing:-.01em; }
113	.card .ctx { color:var(--muted); font-size:15px; max-width:70ch; }
114	.paths { display:grid; grid-template-columns:1fr 1fr; gap:1px; background:var(--line);
115	         border-top:1px solid var(--line); }
116	.path { background:var(--surface2); padding:14px 20px; display:flex;
117	        flex-direction:column; gap:5px; }
118	.plabel { font-family:var(--mono); font-size:10.5px; letter-spacing:.1em;
119	          text-transform:uppercase; }
120	.plabel.a { color:var(--go); } .plabel.b { color:var(--stop); }
121	.ptext { font-size:14.5px; color:var(--muted); }
122	.rec { padding:12px 20px; border-top:1px solid var(--line); font-size:14.5px;
123	       background:color-mix(in srgb, var(--aurora) 7%, transparent); }
124	.rec b { color:var(--ink); }
125	
126	/* --- timeline: ONLY when order carries information the reader needs ---------- */
127	.timeline { display:flex; flex-direction:column; }
128	.tl { display:grid; grid-template-columns:112px 1fr; gap:18px; align-items:start;
129	      padding:16px 0; border-bottom:1px solid var(--line); }
130	.tl:last-child { border-bottom:0; }
131	.tl .when { font-family:var(--mono); font-size:12px; color:var(--dim); padding-top:2px; }
132	.tl .what { display:flex; flex-direction:column; gap:5px; }
133	.tl .wt { font-weight:620; }
134	.tl .wd { color:var(--muted); font-size:14.5px; }
135	
136	/* --- versus: A GENUINE DISAGREEMENT, fairly stated ---------------------------
137	   NOT a pro/con list. Use when two positions are both defensible and the reader must
138	   judge between them. Pair with .synth when a reconciliation exists. */
139	.versus { display:grid; grid-template-columns:1fr 1fr; gap:1px; background:var(--line);
140	          border:1px solid var(--line); border-radius:5px; overflow:hidden; }
141	.side { background:var(--surface); padding:19px 21px; display:flex;
142	        flex-direction:column; gap:8px; }
143	.side .lbl { font-family:var(--mono); font-size:11px; letter-spacing:.1em;
144	             text-transform:uppercase; color:var(--hold); }
145	.side .claim { font-size:16px; font-weight:600; }
146	.side .why { font-size:14.5px; color:var(--muted); }
147	.synth { background:color-mix(in srgb,var(--aurora) 10%, var(--surface));
148	         border:1px solid color-mix(in srgb,var(--aurora) 32%,var(--line));
149	         border-radius:5px; padding:20px 22px; display:flex; flex-direction:column; gap:8px; }
150	.synth .lbl { font-family:var(--mono); font-size:11px; letter-spacing:.1em;
151	              text-transform:uppercase; color:var(--aurora); }
152	
153	/* --- quote: someone's words, verbatim. mark = the phrase that matters -------- */
154	blockquote { margin:0; padding:20px 24px; background:var(--surface);
155	             border-left:3px solid var(--aurora); border-radius:4px;
156	             font-family:var(--serif); font-size:18px; line-height:1.6; }
157	blockquote .who { display:block; margin-top:10px; font-family:var(--mono); font-size:11px;
158	                  letter-spacing:.09em; color:var(--dim); text-transform:uppercase; }
159	mark { background:color-mix(in srgb,var(--hold) 26%,transparent); color:inherit;
160	       padding:0 3px; border-radius:2px; }
161	
162	/* --- rows: a flat list where each item has a label and a consequence --------- */
163	.rows { display:flex; flex-direction:column; border:1px solid var(--line);
164	        border-radius:5px; overflow:hidden; }
165	.row { display:flex; gap:14px; align-items:flex-start; padding:13px 18px;
166	       background:var(--surface); border-bottom:1px solid var(--line); }
167	.row:last-child { border-bottom:0; }
168	.row .rt { font-weight:600; min-width:180px; }
169	.row .rd { color:var(--muted); font-size:14.5px; }
170	
171	/* --- table: wide content scrolls ITSELF, the page never scrolls sideways ----- */
172	.scroll { overflow-x:auto; -webkit-overflow-scrolling:touch; }
173	table { border-collapse:collapse; width:100%; min-width:520px; font-size:14.5px; }
174	th,td { text-align:left; padding:10px 12px; border-bottom:1px solid var(--line);
175	        vertical-align:top; }
176	th { font-family:var(--mono); font-size:11px; letter-spacing:.09em; text-transform:uppercase;
177	     color:var(--dim); font-weight:600; }
178	td.n { font-family:var(--mono); font-variant-numeric:tabular-nums; }
179	.v { font-family:var(--mono); font-size:11px; letter-spacing:.06em; white-space:nowrap; }
180	.v.ok { color:var(--go); } .v.no { color:var(--stop); }
181	.v.cl { color:var(--hold); } .v.mo { color:var(--dim); }
182	
183	footer { margin-top:54px; padding-top:20px; border-top:1px solid var(--line);
184	         font-family:var(--mono); font-size:12px; color:var(--dim); line-height:1.7; }
185	
186	:focus-visible { outline:2px solid var(--aurora); outline-offset:2px; }
187	@media (max-width:640px) {
188	  .paths, .versus { grid-template-columns:1fr; }
189	  .tl { grid-template-columns:1fr; gap:4px; }
190	  .row { flex-direction:column; gap:4px; }
191	}
192	@media (prefers-reduced-motion:reduce) { * { animation:none !important; transition:none !important; } }
193	</style>
194	
195	<!-- ============================================================================
196	     PRIMITIVES AVAILABLE. Compose freely -- this is a system, not a template, and
197	     the shape should fit THIS report rather than the last one.
198	
199	     header / .eyebrow / h1 / .standfirst
200	         Opening. The standfirst is a serif thesis sentence, not a summary.
201	     hr.rule
202	         Section break carrying the project's own colours. Use 2-4 times, never between every section.
203	     .tiles > .tile > .v + .k
204	         3-6 headline NUMBERS. Never prose. Digits are tabular by default.
205	     .card[.go|.hold|.stop] > .head + .paths > .path > .plabel[.a|.b] + .ptext, then .rec
206	         A DECISION WITH REAL COSTS ON BOTH SIDES. .plabel.a names the path you lean toward, .plabel.b the one you do not; .rec carries the recommendation. If one path is obviously wrong it is rhetoric wearing a choice's clothes -- use .rows instead.
207	     .timeline > .tl > .when + .what
208	         ONLY when order carries information the reader needs. Not decoration for a list.
209	     .versus > .side  (+ .synth)
210	         A GENUINE DISAGREEMENT, both sides stated fairly. NOT a pro/con list. Pair with .synth when a reconciliation exists.
211	     blockquote > mark + .who
212	         Someone's words verbatim. mark highlights the phrase that actually matters.
213	     .rows > .row > .rt + .rd
214	         A flat list where each item has a label and a consequence.
215	     .scroll > table  (td.n, .v.ok/.no/.cl/.mo)
216	         Comparison. Wide content scrolls ITSELF so the page never scrolls sideways.
217	     --go / --hold / --stop
218	         SEMANTIC colour: cheap / needs judgement / costs either way. Never decoration.
219	     --aurora
220	         The accent. Structure and emphasis only -- it must never carry status.
221	
222	     RULES THAT ARE NOT NEGOTIABLE:
223	       * Every number verified against the tree before it goes in.
224	       * A finding that failed states that it failed, in the same voice as one that passed.
225	       * Semantic colour carries meaning; --aurora carries none.
226	     ============================================================================ -->
227	
228	<div class="wrap">
229	
230	<header>
231	  <div class="eyebrow">LIVE API AUDIT - 2026-08-10</div>
232	  <h1>REPLACE: the thesis, as a sentence a reader could disagree with.</h1>
233	  <p class="standfirst">REPLACE: what this document is for, and what it will cost the reader
234	  to read it.</p>
235	</header>
236	
237	<hr class="rule">
238	
239	<section>
240	  <h2>Replace this section label</h2>
241	  <p class="prose">Compose from the primitives above. Delete this scaffold comment block and
242	  every placeholder before publishing.</p>
243	</section>
